    @root_validator
    def validate_experiment_consistency(cls, values):
        """验证实验配置的一致性"""
        start_time = values.get('start_time')
        end_time = values.get('end_time')

        # 验证时间范围
        if start_time and end_time and start_time >= end_time:
            raise ValueError('实验开始时间必须早于结束时间')

        # 验证流量分配
        traffic_allocation = values.get('traffic_allocation', {})
        if not traffic_allocation:
            raise ValueError('实验必须包含流量分配配置')

        # 检查是否有对照组
        has_control = any(
            'control' in group_name.lower() 
            for group_name in traffic_allocation.keys()
        )
        if not has_control:
            raise ValueError('实验必须包含对照组')

        # 验证分桶范围不重叠
        bucket_ranges = []
        for allocation in traffic_allocation.values():
            bucket_ranges.append(allocation.bucket_range)

        for i, range1 in enumerate(bucket_ranges):
            for j, range2 in enumerate(bucket_ranges[i+1:], i+1):
                if (range1.start <= range2.end and range2.start <= range1.end):
                    raise ValueError(f'分桶范围存在重叠: {range1} 与 {range2}')

        return values

    @property
    def is_active(self) -> bool:
        """判断实验是否处于活跃状态"""
        now = datetime.now(timezone.utc)
        return (
            self.status == ExperimentStatus.RUNNING and
            self.start_time <= now <= self.end_time
        )

    @property
    def total_traffic_percentage(self) -> float:
        """计算实验总流量百分比"""
        total_buckets = sum(
            allocation.bucket_range.size 
            for allocation in self.traffic_allocation.values()
        )
        return (total_buckets / 10000) * 100.0

    def get_allocation_for_bucket(self, bucket_id: int) -> Optional[TrafficAllocation]:
        """根据分桶ID获取对应的流量分配"""
        for allocation in self.traffic_allocation.values():
            if allocation.bucket_range.contains(bucket_id):
                return allocation
        return None

    def update_status(self, new_status: ExperimentStatus) -> None:
        """更新实验状态"""
        self.status = new_status
        self.updated_at = datetime.now(timezone.utc)

