class LayerExperiment(BaseModel):
    """分层实验模型 - 管理同层内的多个实验"""

    layer_id: LayerType = Field(..., description="层级标识")
    layer_name: str = Field(..., min_length=1, description="层级名称")
    max_experiments: int = Field(default=5, gt=0, description="该层最大实验数量")
    traffic_allocation: float = Field(default=80.0, gt=0, le=100, description="该层参与实验的流量百分比")

    # 当前活跃实验列表
    active_experiments: List[str] = Field(default_factory=list, description="活跃实验ID列表")

    # 互斥性配置
    mutual_exclusion: bool = Field(default=True, description="同层实验是否互斥")

    @validator('active_experiments')
    def validate_max_experiments_limit(cls, v, values):
        """验证活跃实验数量不超过限制"""
        max_experiments = values.get('max_experiments', 5)
        if len(v) > max_experiments:
            raise ValueError(f'活跃实验数量({len(v)})超过限制({max_experiments})')
        return v

    def can_add_experiment(self) -> bool:
        """判断是否可以添加新实验"""
        return len(self.active_experiments) < self.max_experiments

    def add_experiment(self, experiment_id: str) -> bool:
        """添加实验到该层"""
        if not self.can_add_experiment():
            return False

        if experiment_id not in self.active_experiments:
            self.active_experiments.append(experiment_id)
        return True

    def remove_experiment(self, experiment_id: str) -> bool:
        """从该层移除实验"""
        if experiment_id in self.active_experiments:
            self.active_experiments.remove(experiment_id)
            return True
        return False


class HoldoutExperiment(BaseModel):
    """Holdout实验模型 - 用于评估整体系统提升"""

    experiment_id: str = Field(..., min_length=1, description="Holdout实验标识")
    name: str = Field(..., min_length=1, description="Holdout实验名称")
    description: str = Field(default="", description="实验描述")

    # 分组配置
    groups: Dict[str, TrafficAllocation] = Field(..., description="Holdout分组配置")

    # 指标配置
    success_metrics: ExperimentMetrics = Field(..., description="成功指标")

    # 时间配置
    start_time: datetime = Field(..., description="开始时间")
    end_time: datetime = Field(..., description="结束时间") 

    @validator('groups')
    def validate_holdout_groups(cls, v):
        """验证Holdout分组配置"""
        if len(v) < 2:
            raise ValueError('Holdout实验至少需要两个分组')

        # 验证分桶范围不重叠
        bucket_ranges = [group.bucket_range for group in v.values()]
        for i, range1 in enumerate(bucket_ranges):
            for j, range2 in enumerate(bucket_ranges[i+1:], i+1):
                if (range1.start <= range2.end and range2.start <= range1.end):
                    raise ValueError('Holdout分组的分桶范围存在重叠')

        return v


class ReverseExperiment(BaseModel):
    """反转实验模型 - 新策略中保留旧策略用户进行长期观测"""

    experiment_id: str = Field(..., min_length=1, description="反转实验标识")
    name: str = Field(..., min_length=1, description="反转实验名称")
    description: str = Field(default="", description="实验描述")

    # 观测配置
    observation_period_days: int = Field(default=30, gt=0, description="观测期天数")
    reverse_traffic_percentage: float = Field(default=10.0, gt=0, le=50, description="反转流量百分比")

    # 追踪指标
    metrics_to_track: List[str] = Field(default_factory=list, description="需要追踪的指标列表")

    # 时间配置
    start_time: datetime = Field(..., description="开始时间")
    observation_end_time: Optional[datetime] = Field(None, description="观测结束时间")

    @validator('metrics_to_track')
    def validate_tracking_metrics(cls, v):
        """验证追踪指标配置"""
        if not v:
            raise ValueError('反转实验必须指定至少一个追踪指标')

        # 移除重复指标
        return list(set(v))

    @root_validator
    def calculate_observation_end_time(cls, values):
        """计算观测结束时间"""
        start_time = values.get('start_time')
        observation_period = values.get('observation_period_days', 30)

        if start_time and not values.get('observation_end_time'):
            from datetime import timedelta
            values['observation_end_time'] = start_time + timedelta(days=observation_period)

        return values


class ExperimentDependency(BaseModel):
    """实验依赖关系模型"""

    parent_experiment_id: str = Field(..., min_length=1, description="父实验ID")
    child_experiment_id: str = Field(..., min_length=1, description="子实验ID")
    dependency_type: str = Field(default="sequential", description="依赖类型: sequential, parallel")

    @validator('dependency_type')
    def validate_dependency_type(cls, v):
        """验证依赖类型"""
        valid_types = ["sequential", "parallel"]
        if v not in valid_types:
            raise ValueError(f'依赖类型必须是以下之一: {valid_types}')
        return v

    @validator('child_experiment_id')
    def child_must_differ_from_parent(cls, v, values):
        """验证子实验ID不能与父实验ID相同"""
        parent_id = values.get('parent_experiment_id')
        if parent_id and v == parent_id:
            raise ValueError('子实验ID不能与父实验ID相同')
        return v


class SeasonalOverride(BaseModel):
    """季节性配置覆盖模型"""

    season_name: str = Field(..., min_length=1, description="季节名称")
    start_date: datetime = Field(..., description="季节开始日期")
    end_date: datetime = Field(..., description="季节结束日期")

    # 配置覆盖
    config_override: Dict[str, Any] = Field(default_factory=dict, description="配置覆盖")
    experiment_overrides: Dict[str, Dict[str, Any]] = Field(
        default_factory=dict, description="实验特定覆盖"
    )

    @validator('end_date')
    def end_date_after_start(cls, v, values):
        """验证结束日期在开始日期之后"""
        start_date = values.get('start_date')
        if start_date and v <= start_date:
            raise ValueError('季节结束日期必须在开始日期之后')
        return v

    def is_active(self, current_date: datetime) -> bool:
        """判断季节配置是否在当前日期生效"""
        return self.start_date <= current_date <= self.end_date
